//! Untrusted historical provenance only. This decoder never proves physical
//! absence, authorizes cleanup, creates a producer or grants attachment reads.
use super::*;
fn uuid(s:&str)->bool{s.len()==36&&s.bytes().enumerate().all(|(i,b)|if [8,13,18,23].contains(&i){b==b'-'}else{b.is_ascii_digit()||(b'a'..=b'f').contains(&b)})}
fn text<'a>(value:&'a Value,key:&str,max:usize)->Result<&'a str,String>{value[key].as_str().filter(|s|s.len()<=max).ok_or_else(||format!("Portable original disposition {key} missing/bounded"))}
pub(super) fn validate(raw:&str)->Result<BTreeSet<String>,String>{
 let rows:Vec<Value>=serde_json::from_str(raw).map_err(|_|"Portable original disposition array malformed")?;if rows.len()>1024{return Err("Portable original disposition count exceeds bound".into())}let mut ids=BTreeSet::new();
 for row in rows{
  let op=text(&row,"operation_id",36)?;let raw=text(&row,"evidence_json",32*1024*1024)?;
  if row.as_object().map(|o|o.len())!=Some(5)||row["format"]!=1||row["kind"]!="original_discarded_local_cover"||!uuid(op)||!ids.insert(op.to_string())||row["evidence_sha256"]!=sha(raw.as_bytes()){return Err("Portable original disposition identity/hash differs".into())}
  let e:Value=serde_json::from_str(raw).map_err(|_|"Portable original disposition evidence malformed")?;if e.as_object().map(|o|o.len())!=Some(8)||e["format"]!=1{return Err("Portable original disposition evidence shape differs".into())}
  let request_raw=text(&e,"request_json",65536)?;let proof_raw=text(&e,"proof_json",65536)?;let plan_raw=text(&e,"plan_json",32*1024*1024)?;let receipt_raw=text(&e,"receipt_json",65536)?;let acknowledged_raw=text(&e,"acknowledged_chunks_json",32*1024*1024)?;let _:Value=serde_json::from_str(text(&e,"plan_native_stamp_json",65536)?).map_err(|_|"Portable original plan stamp malformed")?;
  let request:Value=serde_json::from_str(request_raw).map_err(|_|"Portable original request malformed")?;let proof:Value=serde_json::from_str(proof_raw).map_err(|_|"Portable original creator malformed")?;let plan:Value=serde_json::from_str(plan_raw).map_err(|_|"Portable original plan malformed")?;let receipt:Value=serde_json::from_str(receipt_raw).map_err(|_|"Portable original receipt malformed")?;let ack:Vec<(i64,String)>=serde_json::from_str(acknowledged_raw).map_err(|_|"Portable original ACK rows malformed")?;
  let hash=sha(request_raw.as_bytes());let length=request["byte_length"].as_u64().filter(|n|*n>0&&*n<=30*1024*1024).ok_or("Portable original request byte bound differs")?;
  if request.as_object().map(|o|o.len())!=Some(8)||request["operation_id"]!=op||e["request_sha256"]!=hash||proof["format"]!=1||proof["request_sha256"]!=hash||plan.as_object().map(|o|o.len())!=Some(10)||plan["format"]!=1||plan["operation_id"]!=op||plan["request_json"]!=request_raw||plan["creator"]!=proof||plan["binding"]!=request["original_binding"]||!plan["payload_sha256"].as_str().is_some_and(valid_sha)||receipt.as_object().map(|o|o.len())!=Some(5)||receipt["format"]!=1||receipt["state"]!="discarded_original_payload"||receipt["operation_id"]!=op||ack.len()>480||serde_json::to_value(&ack).map_err(|e|e.to_string())?!=plan["acknowledged_sql"]{return Err("Portable original request/plan/receipt binding differs".into())}
  let completion_raw=text(&receipt,"native_completion_json",65536)?;let completion:Value=serde_json::from_str(completion_raw).map_err(|_|"Portable original native completion malformed")?;let before=&plan["payload"];let after=&completion["payload_after"];let initial=&plan["completion_initial_stamp"];let actual=&receipt["native_completion_stamp"];
  if completion.as_object().map(|o|o.len())!=Some(7)||completion["format"]!=1||completion["state"]!="discarded_original_payload"||completion["operation_id"]!=op||completion["request_sha256"]!=hash||completion["plan_sha256"]!=sha(plan_raw.as_bytes())||completion["binding"]!=request["original_binding"]||before["device"]!=proof["payload_identity"]["device"]||before["inode"]!=proof["payload_identity"]["inode"]||before["uid"]!=proof["uid"]||before["links"]!=1||after["device"]!=before["device"]||after["inode"]!=before["inode"]||after["uid"]!=before["uid"]||after["mode"]!=before["mode"]||after["length"]!=before["length"]||!after["length"].as_u64().is_some_and(|n|n<=length)||after["links"]!=0||initial["length"]!=0||initial["links"]!=1||actual["links"]!=1||actual["length"]!=completion_raw.len()||!["device","inode","uid","mode"].iter().all(|k|initial[*k]==actual[*k]){return Err("Portable original completion/creator observation differs".into())}
  let metadata=plan["native_metadata"].as_array().filter(|a|a.len()<=480).ok_or("Portable original metadata bound differs")?;let mut chunks=BTreeMap::new();
  for m in metadata{let name=text(m,"name",19)?;if name.len()!=19||!name.starts_with("chunk-")||!name.ends_with(".json")||!name.as_bytes()[6..14].iter().all(|b|b.is_ascii_digit())||!name[6..14].parse::<usize>().is_ok_and(|n|n<480)||chunks.insert(name.to_string(),m).is_some(){return Err("Portable original native chunk roster differs".into())}let bytes:Vec<u8>=serde_json::from_value(m["raw_bytes"].clone()).map_err(|_|"Portable original raw chunk bytes malformed")?;if bytes.len()>65536||m["stamp"]["length"]!=bytes.len()||m["stamp"]["links"]!=1{return Err("Portable original raw chunk bound/stamp differs".into())}}
  for(index,(ordinal,raw))in ack.iter().enumerate(){if *ordinal!=index as i64||raw.len()>65536{return Err("Portable original SQL chunk order differs".into())}let value:Value=serde_json::from_str(raw).map_err(|_|"Portable original SQL chunk malformed")?;let m=chunks.get(&format!("chunk-{index:08}.json")).ok_or("Portable acknowledged native chunk missing")?;let bytes:Vec<u8>=serde_json::from_value(m["raw_bytes"].clone()).map_err(|_|"Portable chunk bytes malformed")?;if value["chunk_file"]!=m["stamp"]||value["raw_chunk"].as_str().map(str::as_bytes)!=Some(bytes.as_slice()){return Err("Portable original SQL/native raw chunk differs".into())}}
 }
 Ok(ids)
}
pub(super) fn protects(value:&Value,pin:&str)->bool{use pulldown_cmark::{Event,Parser,Tag};match value{Value::String(s)=>s==pin||Parser::new(s).any(|event|matches!(event,Event::Start(Tag::Link{dest_url,..}|Tag::Image{dest_url,..})if dest_url.as_ref()==pin)),Value::Array(a)=>a.iter().any(|v|protects(v,pin)),Value::Object(o)=>o.values().any(|v|protects(v,pin)),_=>false}}
/// Logical historical identity reservation only. Input remains provenance, not
/// an original creator, serving or physical-absence capability. The caller must
/// separately hold its actual current canonical/native installation authority.
fn retained_history(portable:&Value)->Result<(BTreeSet<String>,bool),String>{
 fn walk(value:&Value,depth:usize,budget:&mut usize,ids:&mut BTreeMap<String,String>,requires4:&mut bool)->Result<(),String>{
  if value.is_null(){return Ok(())}if depth>8||value["format"]!=1||value["authority"]!="portable_provenance_only"{return Err("Retained portable history shape/depth unavailable".into())}
  if let Some(raw)=value["local_dispositions_json"].as_str(){*requires4=true;if raw.len()>*budget{return Err("Retained portable history exceeds parse budget".into())}*budget-=raw.len();validate(raw)?;let rows:Vec<Value>=serde_json::from_str(raw).map_err(|_|"Retained disposition rows malformed")?;for row in rows{let op=text(&row,"operation_id",36)?.to_string();let hash=text(&row,"evidence_sha256",64)?.to_string();if ids.get(&op).is_some_and(|prior|prior!=&hash){return Err("Conflicting retained original disposition identity".into())}ids.insert(op,hash);if ids.len()>1024{return Err("Retained disposition identity bound exceeded".into())}}}
  if let Some(raw)=value["joint_imports_json"].as_str(){if raw.len()>*budget{return Err("Retained joint history exceeds parse budget".into())}*budget-=raw.len();let rows:Vec<Value>=serde_json::from_str(raw).map_err(|_|"Retained joint history malformed")?;if rows.len()>4096{return Err("Retained joint history count exceeds bound".into())}for row in rows{if row["kind"]=="legacy_canonical_metadata"{*requires4=true}let raw=text(&row,"receipt_json",64*1024*1024)?;if raw.len()>*budget{return Err("Retained nested history exceeds parse budget".into())}*budget-=raw.len();let receipt:Value=serde_json::from_str(raw).map_err(|_|"Retained nested receipt malformed")?;walk(&receipt["imported_provenance"],depth+1,budget,ids,requires4)?;}}
  Ok(())
 }
 let mut budget=128*1024*1024;let mut ids=BTreeMap::new();let mut requires4=false;walk(portable,0,&mut budget,&mut ids,&mut requires4)?;Ok((ids.into_keys().collect(),requires4))
}

pub(crate) fn retained_ids(portable:&Value)->Result<BTreeSet<String>,String>{Ok(retained_history(portable)?.0)}
/// Output-version classification only; never a creator or absence grant.
pub(crate) fn requires_format4(portable:&Value)->Result<bool,String>{Ok(retained_history(portable)?.1)}
